//! Whether a changed file is generated — a lockfile, a bundle, a snapshot, codegen —
//! the churn an agent's change drags along that nobody reviews line by line. Said the
//! way GitHub's linguist says it: `.gitattributes` first (`linguist-generated`,
//! `linguist-vendored`, `-diff`), then well-known names, then a header that says so.
//!
//! It only labels: the file stays in the review until the reviewer ignores it.

use std::collections::HashMap;

/// Files that are generated by name alone, wherever they live.
const GENERATED_NAMES: &[&str] = &[
    "package-lock.json",
    "npm-shrinkwrap.json",
    "yarn.lock",
    "pnpm-lock.yaml",
    "bun.lock",
    "bun.lockb",
    "deno.lock",
    "Cargo.lock",
    "Gemfile.lock",
    "poetry.lock",
    "Pipfile.lock",
    "uv.lock",
    "pdm.lock",
    "composer.lock",
    "go.sum",
    "flake.lock",
    "mix.lock",
    "pubspec.lock",
    "Podfile.lock",
    "Package.resolved",
    "packages.lock.json",
    "gradle.lockfile",
    "routeTree.gen.ts",
    "auto-imports.d.ts",
    "components.d.ts",
    "next-env.d.ts",
];

/// Endings of generated file names: minified bundles, source maps, test snapshots,
/// protobuf and other codegen output.
const GENERATED_SUFFIXES: &[&str] = &[
    ".min.js",
    ".min.mjs",
    ".min.css",
    ".js.map",
    ".mjs.map",
    ".css.map",
    ".d.ts.map",
    ".snap",
    ".gen.ts",
    ".gen.js",
    ".generated.ts",
    ".generated.js",
    ".generated.cs",
    ".g.dart",
    ".freezed.dart",
    ".pb.go",
    ".pb.ts",
    "_pb2.py",
    "_pb2.pyi",
    "_pb2_grpc.py",
    ".designer.cs",
];

/// Folders whose contents are generated.
const GENERATED_DIRS: &[&str] = &["__snapshots__", "__generated__", "node_modules"];

/// Words a generated file's header says about itself, lowercased.
const HEADER_MARKERS: &[&str] = &[
    "@generated",
    "do not edit",
    "auto-generated",
    "autogenerated",
    "automatically generated",
    "code generated by",
    "this file is generated",
    "this file was generated",
];

/// How much of a file's head is read for a marker.
pub const HEADER_BYTES: usize = 1024;
/// How many of its first lines.
const HEADER_LINES: usize = 5;

/// Generated by its path: a well-known name, ending, or folder.
pub fn by_path(path: &str) -> bool {
    let name = path.rsplit('/').next().unwrap_or(path);
    GENERATED_NAMES.contains(&name)
        || GENERATED_SUFFIXES.iter().any(|s| name.ends_with(s))
        || path.split('/').rev().skip(1).any(|dir| GENERATED_DIRS.contains(&dir))
}

/// Generated by what its first lines say about it.
pub fn by_header(head: &[u8]) -> bool {
    let head = &head[..head.len().min(HEADER_BYTES)];
    String::from_utf8_lossy(head)
        .lines()
        .take(HEADER_LINES)
        .map(str::to_lowercase)
        .any(|line| HEADER_MARKERS.iter().any(|m| line.contains(m)))
}

/// One `.gitattributes` line that has a say on generatedness.
struct Rule {
    pattern: String,
    /// Whether the pattern names a path from the attributes file's folder (it has a
    /// slash other than a trailing one), rather than a name at any depth below it.
    anchored: bool,
    generated: bool,
}

/// Every `.gitattributes` file's rules, by the folder it sits in (`""` for the root).
pub struct Attributes {
    by_dir: HashMap<String, Vec<Rule>>,
}

impl Attributes {
    /// The attributes that apply to `paths`: the `.gitattributes` of every folder
    /// above them, read through `read` (repo-relative path → text, `None` if absent).
    pub fn load(paths: &[&str], read: &dyn Fn(&str) -> Option<String>) -> Attributes {
        let mut by_dir = HashMap::new();
        for path in paths {
            for dir in ancestors(path) {
                if by_dir.contains_key(dir) {
                    continue;
                }
                let file = if dir.is_empty() {
                    ".gitattributes".to_string()
                } else {
                    format!("{dir}/.gitattributes")
                };
                let rules = read(&file).map(|text| parse(&text)).unwrap_or_default();
                by_dir.insert(dir.to_string(), rules);
            }
        }
        Attributes { by_dir }
    }

    /// What the attributes say about `path`: generated, explicitly not, or nothing.
    /// A deeper file outranks a shallower one, and a later line an earlier one, as git
    /// reads them.
    pub fn generated(&self, path: &str) -> Option<bool> {
        let mut verdict = None;
        for dir in ancestors(path).collect::<Vec<_>>().into_iter().rev() {
            let Some(rules) = self.by_dir.get(dir) else {
                continue;
            };
            let rel = if dir.is_empty() {
                path
            } else {
                &path[dir.len() + 1..]
            };
            for rule in rules {
                let subject = if rule.anchored {
                    rel
                } else {
                    rel.rsplit('/').next().unwrap_or(rel)
                };
                if glob_match(&rule.pattern, subject) {
                    verdict = Some(rule.generated);
                }
            }
        }
        verdict
    }
}

/// The folders above `path`, deepest first, ending with the root (`""`).
fn ancestors(path: &str) -> impl Iterator<Item = &str> {
    let mut cut = Some(path.len());
    std::iter::from_fn(move || {
        let end = cut?;
        let dir = path[..end].rfind('/').map(|i| &path[..i]);
        cut = dir.map(str::len);
        Some(dir.unwrap_or(""))
    })
}

fn parse(text: &str) -> Vec<Rule> {
    let mut rules = Vec::new();
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut parts = line.split_whitespace();
        let Some(pattern) = parts.next() else {
            continue;
        };
        let mut generated = None;
        for attr in parts {
            match attr {
                "linguist-generated" | "linguist-generated=true" | "linguist-vendored"
                | "linguist-vendored=true" | "-diff" => generated = Some(true),
                "-linguist-generated" | "linguist-generated=false" | "-linguist-vendored"
                | "linguist-vendored=false" | "diff" => generated = Some(false),
                _ => {}
            }
        }
        let Some(generated) = generated else {
            continue;
        };
        // As in git, a pattern naming a folder doesn't reach inside it — that takes
        // `dir/**` — so a trailing slash only gets in the way.
        let trimmed = pattern.trim_end_matches('/');
        rules.push(Rule {
            pattern: trimmed.trim_start_matches('/').to_string(),
            anchored: trimmed.contains('/'),
            generated,
        });
    }
    rules
}

/// Shell-style matching with git's `**`: `*` and `?` stay within one folder, `**`
/// spans any number of them (none included).
pub fn glob_match(pattern: &str, text: &str) -> bool {
    fn go(p: &[u8], t: &[u8]) -> bool {
        match p.first() {
            None => t.is_empty(),
            Some(b'*') if p.get(1) == Some(&b'*') => {
                // `**/` matches zero or more folders; a trailing `**` everything.
                let rest = &p[2..];
                let rest = rest.strip_prefix(b"/").unwrap_or(rest);
                if rest.is_empty() {
                    return true;
                }
                (0..=t.len()).any(|i| (i == 0 || t[i - 1] == b'/') && go(rest, &t[i..]))
            }
            Some(b'*') => {
                let rest = &p[1..];
                (0..=t.len())
                    .take_while(|&i| i == 0 || t[i - 1] != b'/')
                    .any(|i| go(rest, &t[i..]))
            }
            Some(b'?') => t.first().is_some_and(|&c| c != b'/') && go(&p[1..], &t[1..]),
            Some(&c) => t.first() == Some(&c) && go(&p[1..], &t[1..]),
        }
    }
    go(pattern.as_bytes(), text.as_bytes())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn well_known_names_endings_and_folders() {
        assert!(by_path("package-lock.json"));
        assert!(by_path("web/pnpm-lock.yaml"));
        assert!(by_path("static/app.min.js"));
        assert!(by_path("dist/app.js.map"));
        assert!(by_path("src/__snapshots__/Button.test.tsx.snap"));
        assert!(by_path("src/__generated__/graphql.ts"));
        assert!(by_path("src/routeTree.gen.ts"));
        assert!(!by_path("src/package.ts"));
        assert!(!by_path("src/lock.json"));
        assert!(!by_path("src/minimal.js"));
    }

    #[test]
    fn a_header_that_says_so() {
        assert!(by_header(b"// Code generated by protoc-gen-go. DO NOT EDIT.\npackage x\n"));
        assert!(by_header(b"/* eslint-disable */\n// @generated by relay\n"));
        assert!(by_header(b"# This file is automatically generated by uv.\n"));
        assert!(!by_header(b"import x from 'y'\n\n\n\n\n// do not edit below\n"));
        assert!(!by_header(b"export const generated = 1;\n"));
    }

    fn attrs(files: &[(&str, &str)], paths: &[&str]) -> Attributes {
        let files: HashMap<String, String> =
            files.iter().map(|(p, t)| (p.to_string(), t.to_string())).collect();
        Attributes::load(paths, &|p| files.get(p).cloned())
    }

    #[test]
    fn gitattributes_mark_and_unmark() {
        let a = attrs(
            &[
                (
                    ".gitattributes",
                    "# codegen\n*.pb.ts linguist-generated\napi/client/** linguist-generated=true\n**/vendor/** linguist-vendored\npackage-lock.json -linguist-generated\n",
                ),
                ("web/.gitattributes", "schema.ts linguist-generated\n/local.ts -diff\n"),
            ],
            &[
                "src/a.pb.ts",
                "api/client/x/y.ts",
                "lib/vendor/z.js",
                "package-lock.json",
                "web/deep/schema.ts",
                "web/local.ts",
                "web/deep/local.ts",
                "src/plain.ts",
            ],
        );
        assert_eq!(a.generated("src/a.pb.ts"), Some(true));
        assert_eq!(a.generated("api/client/x/y.ts"), Some(true));
        assert_eq!(a.generated("lib/vendor/z.js"), Some(true));
        assert_eq!(a.generated("package-lock.json"), Some(false), "explicitly not");
        assert_eq!(a.generated("web/deep/schema.ts"), Some(true), "unanchored: any depth");
        assert_eq!(a.generated("web/local.ts"), Some(true));
        assert_eq!(a.generated("web/deep/local.ts"), None, "anchored to web/");
        assert_eq!(a.generated("src/plain.ts"), None);
    }

    #[test]
    fn globs() {
        assert!(glob_match("*.ts", "a.ts"));
        assert!(!glob_match("*.ts", "x/a.ts"));
        assert!(glob_match("**/*.ts", "x/y/a.ts"));
        assert!(glob_match("**/*.ts", "a.ts"));
        assert!(glob_match("src/**", "src/a/b"));
        assert!(glob_match("a/**/b", "a/b"));
        assert!(glob_match("a/**/b", "a/x/y/b"));
        assert!(glob_match("?.js", "a.js"));
        assert!(!glob_match("?.js", "ab.js"));
    }
}
